export async function ankiRequest(endpoint,action,params={},key='',fetcher=fetch){const u=new URL(endpoint);if(!['localhost','127.0.0.1','[::1]'].includes(u.hostname)||!['http:','https:'].includes(u.protocol))throw Error('Use AnkiConnect on this computer’s loopback address.');const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),7000);try{const response=await fetcher(u.href,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,version:6,params,...(key?{key}:{})}),signal:controller.signal});if(!response.ok)throw Error(`AnkiConnect HTTP ${response.status}`);const result=await response.json();if(!result||!('result'in result)||!('error'in result))throw Error('Invalid AnkiConnect response');if(result.error)throw Error(result.error);return result.result;}finally{clearTimeout(timeout);}}
